if input requires grad, produces the following graph:
graph(%0 : Float(10240, 1024)) {
  %1 : float = prim::Constant[value=0.5]()
  %2 : Byte(10240, 1024) = aten::lt(%0, %1)
  %3 : Float(10240, 1024) = aten::type_as(%2, %0)
  %4 : Float(10240, 1024) = aten::mul(%3, %0)
  %5 : Float(10240, 1024) = aten::relu(%4)
  return (%5);
}

graph(%0 : Float(*, *)) {
  %1 : float = prim::Constant[value=0.5]()
  %2 : Byte(*, *) = aten::lt(%0, %1)
  %6 : Float(*, *) = prim::DifferentiableGraph_0(%2, %0)
  return (%6);
}
with prim::DifferentiableGraph_0 = graph(%1 : Byte(*, *)
      %2 : Float(*, *)) {
  %18 : Float(*, *), %19 : Float(*, *) = prim::FusionGroup_0[device=0](%2, %1)
  return (%18, %19);
}
with prim::FusionGroup_0 = graph(%3 : Float(*, *)
      %5 : Byte(*, *)) {
  %6 : Float(*, *) = aten::type_as(%5, %3)
  %4 : Float(*, *) = aten::mul(%6, %3)
  %1 : Float(*, *) = aten::relu(%4)
  return (%1, %6);
}

Note that aten::lt is outside of DifferentiableGraph and FusionGroup
